package com.hrcoresystem.hrcore_api.modules.tenant.contracts.infrastructure.api;
import com.hrcoresystem.hrcore_api.common.response.ApiResponse; import com.hrcoresystem.hrcore_api.modules.tenant.contracts.application.dto.ContractResponse; import com.hrcoresystem.hrcore_api.modules.tenant.contracts.application.service.*; import com.hrcoresystem.hrcore_api.modules.tenant.contracts.domain.model.*; import com.hrcoresystem.hrcore_api.modules.tenant.employees.application.service.CurrentEmployeeResolver; import java.util.UUID; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.web.bind.annotation.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.http.*;
@RestController @RequestMapping("/api/me/contracts") public class MyContractController {private final ContractManagementService service;private final ContractPdfService pdf;private final CurrentEmployeeResolver current;public MyContractController(ContractManagementService s,ContractPdfService p,CurrentEmployeeResolver c){service=s;pdf=p;current=c;}
 @GetMapping @PreAuthorize("isAuthenticated()") public ApiResponse<Page<ContractResponse>> list(@RequestParam(required=false) ContractStatus status,@PageableDefault(size=25) Pageable page){current.require();return ApiResponse.success("Contratos propios consultados correctamente",service.list(new ContractFilter(current.id(),null,status,null,null),page));}
 @GetMapping("/{id}") @PreAuthorize("isAuthenticated()") public ApiResponse<ContractResponse> detail(@PathVariable UUID id){current.require();ContractResponse r=service.get(id);if(!r.employeeId().equals(current.id()))throw new org.springframework.security.access.AccessDeniedException("El contrato no pertenece al empleado autenticado");return ApiResponse.success("Contrato propio consultado correctamente",r);}
 @GetMapping(value="/{id}/document",produces=MediaType.APPLICATION_PDF_VALUE) @PreAuthorize("isAuthenticated()") public ResponseEntity<byte[]> document(@PathVariable UUID id){current.require();ContractResponse r=service.get(id);if(!r.employeeId().equals(current.id()))throw new org.springframework.security.access.AccessDeniedException("El contrato no pertenece al empleado autenticado");var result=pdf.generate(id);return ResponseEntity.ok().contentType(MediaType.APPLICATION_PDF).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+result.filename()+"\"").body(result.content());}
}
